css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader::before { content: ''; position: absolute; inset: 0; margin: auto; width: 22%; height: 22%; border-radius: 50%; background: radial-gradient(circle at 40% 35%, #fff, var(--accent) 60%); box-shadow: 0 0 calc(var(--loader-size) * .18) var(--accent); }
.loader span { position: absolute; inset: 0; margin: auto; border: 1px solid color-mix(in srgb, var(--accent-2) 30%, transparent); border-radius: 50%; }
.loader span::after { content: ''; position: absolute; top: calc(var(--loader-size) * -.045); left: 50%; width: calc(var(--loader-size) * .09); height: calc(var(--loader-size) * .09); margin-left: calc(var(--loader-size) * -.045); border-radius: 50%; background: var(--accent-2); box-shadow: 0 0 calc(var(--loader-size) * .08) var(--accent-2); }
.loader span:nth-child(1) { width: 46%; height: 46%; animation: orbit calc(var(--loader-speed) * 1.6) linear infinite; }
.loader span:nth-child(2) { width: 72%; height: 72%; animation: orbit calc(var(--loader-speed) * 2.7) linear infinite; }
.loader span:nth-child(3) { width: 98%; height: 98%; animation: orbit calc(var(--loader-speed) * 4) linear infinite; }
@keyframes orbit { to { rotate: 360deg; } }
